    /**
     * @param array<string, string> $attr Extra attributes e.g. ['class' => 'h-5 w-5']
     */
    public static function svg(string $name, array $attr = []): string
    {
        $inner = self::paths($name);
        if ($inner === null) {
            return '<!-- unknown heroicon: ' . htmlspecialchars($name, ENT_QUOTES, 'UTF-8') . ' -->';
        }
        $class = $attr['class'] ?? 'h-5 w-5 shrink-0';
        $aria = $attr['aria-hidden'] ?? 'true';
        $extra = '';
        foreach ($attr as $k => $v) {
            if ($k === 'class' || $k === 'aria-hidden') {
                continue;
            }
            $extra .= ' ' . htmlspecialchars((string) $k, ENT_QUOTES, 'UTF-8') . '="' . htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8') . '"';
        }
        return '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" '
            . 'class="' . htmlspecialchars($class, ENT_QUOTES, 'UTF-8') . '" aria-hidden="' . htmlspecialchars((string) $aria, ENT_QUOTES, 'UTF-8') . '"' . $extra . '>' . $inner . '</svg>';
    }

